local v2 = Instance.new('ModuleScript', v9)
v2.Name = "element"

Modules[v2] = function(script, require)
    local creator = require(script.Parent.Parent.modules.creator)
    local tween = require(script.Parent.Parent.modules.tween)
    
    local new = creator.new
    local addSignal = creator.addSignal
    
    return function (title, desc, parent, hover)
        local element = {
            hovering = false,
        }
    
        element.title = new("TextLabel", {
            TextWrapped = true,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            FontFace = Font.new("rbxassetid://12187365364", Enum.FontWeight.SemiBold, Enum.FontStyle.Normal),
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 10),
            AutomaticSize = Enum.AutomaticSize.Y,
            Text = title,
            themeTag = {
                TextColor3 = "primary",
                TextTransparency = "primaryTransparency"
            }
        })
    
        element.labelHolder = new("Frame", {
            BackgroundTransparency = 1,
            AutomaticSize = Enum.AutomaticSize.Y,
            Size = UDim2.new(1, -120, 0, 0),
        }, {
            element.title,
            new("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
