-- /home/ubuntu/hirimi-tmp/Hirimi-Library-main/src/themes\init

Modules[v457] = function(script, require)
    local themes = {}
    
    for _, theme in script:GetChildren() do
        local required = require(theme)
        themes[required.name] = required
    end
    
    return themes
end

